-- The library database of Daijishou 1.5.0 (versionCode 416), Room schema version 17,
-- exactly as its DaijishouDatabase_Impl.createAllTables makes it. The gameconsole-emu
-- service builds Daijishou.db from this plus the rows in daijishou-seed.txt, so Daijishou
-- opens it as its own (same identity hash and user_version). A newer Daijishou migrates
-- it forward with its own migrations. The host test checks every statement against the
-- dex of apps/Daijishou/Daijishou.apk.
CREATE TABLE IF NOT EXISTS `PlatformEntity` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `unique_id` TEXT, `name` TEXT NOT NULL, `shortname` TEXT NOT NULL, `description` TEXT, `is_visible` INTEGER NOT NULL, `scrape_preview_media` INTEGER NOT NULL, `wallpaper_path` TEXT, `thumbnail_path` TEXT, `color_theme` INTEGER, `color_on_theme` INTEGER, `accept_filename_regex` TEXT NOT NULL, `default_player_id` INTEGER NOT NULL, `player_id_list` TEXT NOT NULL, `scraper_source_list` TEXT NOT NULL, `box_art_aspect_ratio_id` INTEGER NOT NULL, `use_custom_box_art_aspect_ratio` INTEGER NOT NULL, `custom_box_art_aspect_ratio` TEXT, `screen_aspect_ratio_id` INTEGER NOT NULL, `use_custom_screen_aspect_ratio` INTEGER NOT NULL, `custom_screen_aspect_ratio` TEXT, `items_sync_tree_uri_list` TEXT NOT NULL, `retro_achievements_console_id_list` TEXT NOT NULL, `extra` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `PlayerEntity` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `unique_id` TEXT, `player` INTEGER NOT NULL, `name` TEXT NOT NULL, `description` TEXT, `am_start_arguments` TEXT NOT NULL, `kill_package_processes` INTEGER NOT NULL, `kill_package_processes_warning` INTEGER NOT NULL, `accepted_filename_regex` TEXT NOT NULL, `extra` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `PlayableItemEntity` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `is_singleton_disjoint_set` INTEGER NOT NULL, `use_disjoint_set_primary_playable_item` INTEGER NOT NULL, `disjoint_set_primary_playable_item_id` INTEGER, `playable_item_type` INTEGER NOT NULL, `name` TEXT NOT NULL, `do_scrape_name` INTEGER NOT NULL, `description` TEXT, `scraper_keyword_list` TEXT NOT NULL, `scrape_scraper_keywords` INTEGER NOT NULL, `is_favorite` INTEGER NOT NULL, `is_searchable` INTEGER NOT NULL, `is_visible` INTEGER NOT NULL, `preview_media_path` TEXT, `attached_platform_id` INTEGER, `uri` TEXT NOT NULL, `sync_tree_uri` TEXT NOT NULL, `md5` TEXT NOT NULL, `activity_component_string` TEXT, `use_custom_player` INTEGER NOT NULL, `custom_player_id` INTEGER, `play_count` INTEGER NOT NULL, `last_played_timestamp` INTEGER, `added_date_timestamp` INTEGER NOT NULL, `extra` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `EventEntity` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `event` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `playable_item_id` INTEGER, `platform_id` INTEGER, `player_id` INTEGER, `parcelable` TEXT, `extra` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `PlayableItemToGenrePairEntity` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `playable_item_id` INTEGER NOT NULL, `genre_id` TEXT NOT NULL, `extra` TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_PlayableItemToGenrePairEntity_playable_item_id_genre_id` ON `PlayableItemToGenrePairEntity` (`playable_item_id`, `genre_id`);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
INSERT OR REPLACE INTO room_master_table (id,identity_hash) VALUES(42, 'f60f1e7298a328e7aef8f70a5a947a3a');
PRAGMA user_version = 17;
